VALUES ('sima-yi', '司马懿', 'wei', ARRAY[]::text[], NULL, NULL, 179, 1, NULL, 'year', 251, 9, NULL, 'month', ARRAY['政治家','军事家'], '曹魏权臣，正始十年发动高平陵之变，控制曹魏朝政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马懿"}]'::jsonb, NULL, NULL, NULL)
