VALUES ('sun-hao', '孙皓', 'wu', ARRAY[]::text[], NULL, NULL, 242, 1, NULL, 'year', 284, 1, NULL, 'year', ARRAY['皇帝'], '孙权之孙、孙和之子，264年孙休去世后被拥立为帝，在位至280年。初立时曾开仓赈贫、释放宫女，后渐趋专断，吴国又因交州动乱与对晋战事而局势恶化；280年晋军攻入建业，孙皓出降，孙吴灭亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙皓"}]'::jsonb, NULL, NULL, '吴末帝')
